import { cx } from '@emotion/css';
import Skeleton from 'react-loading-skeleton';

import {
  type DisplayProcessor,
  type Field,
  FieldType,
  formattedValueToString,
  getDisplayProcessor,
  getFieldDisplayName,
} from '@grafana/data';
import { Trans, t } from '@grafana/i18n';
import { config, useDataSourceInstanceSettings } from '@grafana/runtime';
import { type PanelPluginMetas } from '@grafana/runtime/internal';
import { Checkbox, Icon, type IconName, TagList, Text, Tooltip } from '@grafana/ui';
import { formatDate } from 'app/core/internationalization/dates';
import { PluginIconName } from 'app/features/plugins/admin/types';

import { DescriptionTooltip } from '../../components/DescriptionTooltip';
import { type QueryResponse, type SearchResultMeta } from '../../service/types';
import {
  DELETED_BY_UNKNOWN,
  formatDeletedByDisplayValue,
  getIconForKind,
  parseDeletionTimestamp,
} from '../../service/utils';
import { type SelectionChecker, type SelectionToggle } from '../selection';

import { type TableColumn } from './SearchResultsTable';

const TYPE_COLUMN_WIDTH = 175;
const DELETED_COLUMN_WIDTH = 200;
const DATASOURCE_COLUMN_WIDTH = 200;
const DELETED_BY_COLUMN_WIDTH = 200;

export const generateColumns = (
  response: QueryResponse,
  availableWidth: number,
  selection: SelectionChecker | undefined,
  selectionToggle: SelectionToggle | undefined,
  clearSelection: () => void,
  styles: { [key: string]: string },
  onTagSelected: (tag: string) => void,
  onDatasourceChange?: (datasource?: string) => void,
  showingEverything?: boolean,
  panelPluginMetas: PanelPluginMetas = {}
): TableColumn[] => {
  const columns: TableColumn[] = [];
  const access = response.view.fields;
  const uidField = access.uid;
  const kindField = access.kind;
  let sortFieldWith = 0;
  const sortField: Field = access[response.view.dataFrame.meta?.custom?.sortBy];
  if (sortField) {
    sortFieldWith = 175;
    if (sortField.type === FieldType.time) {
      sortFieldWith += 25;
    }
    availableWidth -= sortFieldWith; // pre-allocate the space for the last column
  }

  let width = 50;
  if (selection && selectionToggle) {
    width = 0;
    columns.push({
      id: `column-checkbox`,
      width,
      Header: () => {
        const { view } = response;
        const hasSelection = selection('*', '*');
        const allSelected = view.every((item) => selection(item.kind, item.uid));
        return (
          <Checkbox
            indeterminate={!allSelected && hasSelection}
            checked={allSelected}
            disabled={!response}
            onChange={(e) => {
              if (hasSelection) {
                clearSelection();
              } else {
                for (let i = 0; i < view.length; i++) {
                  const item = view.get(i);
                  selectionToggle(item.kind, item.uid);
                }
              }
            }}
          />
        );
      },
      Cell: (p) => {
        const uid = uidField.values[p.row.index];
        const kind = kindField ? kindField.values[p.row.index] : 'dashboard'; // HACK for now
        const selected = selection(kind, uid);
        const hasUID = uid != null; // Panels don't have UID! Likely should not be shown on pages with manage options
        const { key, ...cellProps } = p.cellProps;
        return (
          <div key={key} {...cellProps} className={styles.cell}>
            <Checkbox
              disabled={!hasUID}
              value={selected && hasUID}
              onChange={(e) => {
                selectionToggle(kind, uid);
              }}
            />
          </div>
        );
      },
      field: uidField,
    });
    availableWidth -= width;
  }

  // Name column
  width = Math.max(availableWidth * 0.2, 300);
  columns.push({
    Cell: (p) => {
      let classNames = cx(styles.nameCellStyle);
      let name = access.name.values[p.row.index];
      const isDeleted = access.isDeleted?.values[p.row.index];
      const description = access.description?.values[p.row.index];

      if (!name?.length) {
        const loading = p.row.index >= response.view.dataFrame.length;
        name = loading ? 'Loading...' : 'Missing title'; // normal for panels
        classNames += ' ' + styles.missingTitleText;
      }
      const { key, ...cellProps } = p.cellProps;
      const isLoaded = response.isItemLoaded(p.row.index);

      return (
        <div key={key} className={cx(styles.cell, isLoaded && description && styles.nameCell)} {...cellProps}>
          {!isLoaded ? (
            <Skeleton width={200} />
          ) : isDeleted || !p.userProps.href ? (
            <span className={classNames}>{name}</span>
          ) : (
            <a href={p.userProps.href} onClick={p.userProps.onClick} className={classNames} title={name}>
              {name}
            </a>
          )}
          {isLoaded ? <DescriptionTooltip description={description} /> : null}
        </div>
      );
    },
    id: `column-name`,
    field: access.name!,
    Header: () => <div>{t('search.results-table.name-header', 'Name')}</div>,
    width,
  });
  availableWidth -= width;

  const deletionTimestampField = access.deletionTimestamp;
  if (deletionTimestampField) {
    width = DELETED_COLUMN_WIDTH;
    columns.push(makeDeletedColumn(response, deletionTimestampField, width, styles));
    availableWidth -= width;
  } else {
    width = TYPE_COLUMN_WIDTH;
    columns.push(makeTypeColumn(response, access.kind, access.panel_type, width, styles, panelPluginMetas));
    availableWidth -= width;
  }

  const deletedByField = access.deletedBy;
  if (deletedByField && hasValue(deletedByField)) {
    width = DELETED_BY_COLUMN_WIDTH;
    columns.push({
      id: `column-deleted-by`,
      field: deletedByField,
      Header: t('search.results-table.deleted-by-header', 'Deleted by'),
      width,
      Cell: (p) => {
        const rawValue = deletedByField.values[p.row.index];
        const { key, ...cellProps } = p.cellProps;
        return (
          <div key={key} {...cellProps} className={styles.cell}>
            {!response.isItemLoaded(p.row.index) ? (
              <Skeleton width={150} />
            ) : rawValue === DELETED_BY_UNKNOWN ? (
              <Tooltip
                content={t(
                  'search.results-table.deleted-by-unknown-tooltip',
                  'Failed to look up the account that deleted this dashboard'
                )}
              >
                <Text variant="body" truncate>
                  <Trans i18nKey="search.results-table.deleted-by-unknown-short">
                    <Icon name="exclamation-triangle" /> Unknown
                  </Trans>
                </Text>
              </Tooltip>
            ) : (
              <Text variant="body" truncate>
                {formatDeletedByDisplayValue(rawValue, t)}
              </Text>
            )}
          </div>
        );
      },
    });
    availableWidth -= width;
  }

  // Show datasources if we have any
  if (access.ds_uid && onDatasourceChange) {
    width = Math.min(availableWidth / 2.5, DATASOURCE_COLUMN_WIDTH);
    columns.push(
      makeDataSourceColumn(
        access.ds_uid,
        width,
        styles.typeIcon,
        styles.datasourceItem,
        styles.invalidDatasourceItem,
        onDatasourceChange
      )
    );
    availableWidth -= width;
  }

  const showTags = !showingEverything || hasValue(response.view.fields.tags);
  const meta = response.view.dataFrame.meta?.custom as SearchResultMeta;
  if (meta?.locationInfo && availableWidth > 0) {
    width = showTags ? Math.max(availableWidth / 1.75, 300) : availableWidth;
    availableWidth -= width;
    columns.push({
      Cell: (p) => {
        const parts = (access.location?.values[p.row.index] ?? '').split('/');
        const { key, ...cellProps } = p.cellProps;
        return (
          <div key={key} {...cellProps} className={styles.cell}>
            {!response.isItemLoaded(p.row.index) ? (
              <Skeleton width={150} />
            ) : (
              <div className={styles.locationContainer}>
                {parts.map((p) => {
                  let info = meta.locationInfo[p];
                  if (!info && p === 'general') {
                    info = { kind: 'folder', url: '/dashboards', name: 'Dashboards' };
                  }

                  if (info) {
                    const content = (
                      <>
                        <Icon name={getIconForKind(info.kind)} />

                        <Text variant="body" truncate>
                          {info.name}
                        </Text>
                      </>
                    );

                    if (info.url) {
                      return (
                        <a key={p} href={info.url} className={styles.locationItem}>
                          {content}
                        </a>
                      );
                    }

                    return (
                      <div key={p} className={styles.locationItem}>
                        {content}
                      </div>
                    );
                  }

                  return <span key={p}>{p}</span>;
                })}
              </div>
            )}
          </div>
        );
      },
      id: `column-location`,
      field: access.location ?? access.url,
      Header: t('search.results-table.location-header', 'Location'),
      width,
    });
  }

  if (availableWidth > 0 && showTags) {
    columns.push(makeTagsColumn(response, access.tags, availableWidth, styles, onTagSelected));
  }

  if (sortField && sortFieldWith) {
    const disp = sortField.display ?? getDisplayProcessor({ field: sortField, theme: config.theme2 });

    columns.push({
      Header: getFieldDisplayName(sortField),
      Cell: (p) => {
        const { key, ...cellProps } = p.cellProps;
        return (
          <div key={key} {...cellProps} className={styles.cell}>
            {getDisplayValue({
              sortField,
              getDisplay: disp,
              index: p.row.index,
              kind: access.kind,
            })}
          </div>
        );
      },
      id: `column-sort-field`,
      field: sortField,
      width: sortFieldWith,
    });
  }

  return columns;
};

function hasValue(f: Field): boolean {
  for (let i = 0; i < f.values.length; i++) {
    if (f.values[i] != null) {
      return true;
    }
  }
  return false;
}

interface DataSourceItemProps {
  dsUid: string;
  iconClass: string;
  invalidDatasourceItemClass: string;
  onDatasourceChange: (datasource?: string) => void;
}

function DataSourceItem({ dsUid, iconClass, invalidDatasourceItemClass, onDatasourceChange }: DataSourceItemProps) {
  const { isLoading, settings } = useDataSourceInstanceSettings(dsUid);
  const icon = settings?.meta?.info?.logos?.small;

  // While the settings are being resolved we don't yet know whether the datasource
  // is valid, so avoid flashing the invalid-datasource fallback.
  if (isLoading) {
    return null;
  }

  if (settings && icon) {
    return (
      // TODO: fix keyboard a11y
      // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions
      <span
        onClick={(e) => {
          e.stopPropagation();
          e.preventDefault();
          onDatasourceChange(settings.uid);
        }}
      >
        <img src={icon} alt="" width={14} height={14} title={settings.type} className={iconClass} />
        {settings.name}
      </span>
    );
  }

  return <span className={invalidDatasourceItemClass}>{dsUid}</span>;
}

function makeDataSourceColumn(
  field: Field<string[]>,
  width: number,
  iconClass: string,
  datasourceItemClass: string,
  invalidDatasourceItemClass: string,
  onDatasourceChange: (datasource?: string) => void
): TableColumn {
  return {
    id: `column-datasource`,
    field,
    Header: t('search.results-table.datasource-header', 'Data source'),
    Cell: (p) => {
      const dslist = field.values[p.row.index];
      if (!dslist?.length) {
        return null;
      }
      const { key, ...cellProps } = p.cellProps;
      return (
        <div key={key} {...cellProps} className={cx(datasourceItemClass)}>
          {dslist.map((v, i) => (
            <DataSourceItem
              key={i}
              dsUid={v}
              iconClass={iconClass}
              invalidDatasourceItemClass={invalidDatasourceItemClass}
              onDatasourceChange={onDatasourceChange}
            />
          ))}
        </div>
      );
    },
    width,
  };
}

// The retention window lives in server config, so the page can only say when an
// object was deleted, not how long is left before it is removed for good.
function makeDeletedColumn(
  response: QueryResponse,
  deletedField: Field<string | undefined>,
  width: number,
  styles: Record<string, string>
): TableColumn {
  return {
    id: 'column-deleted',
    field: deletedField,
    width,
    Header: t('search.results-table.deleted-header', 'Deleted on'),
    Cell: (p) => {
      const deletedAt = deletedField.values[p.row.index];
      const { key, ...cellProps } = p.cellProps;

      if (!response.isItemLoaded(p.row.index)) {
        return (
          <div key={key} {...cellProps} className={cx(styles.cell, styles.typeCell)}>
            <Skeleton width={100} />
          </div>
        );
      }

      // An object deleted before deletion times were recorded has none, so say so rather
      // than leaving the cell looking like it is still loading.
      const deletedDate = parseDeletionTimestamp(deletedAt);
      if (!deletedDate) {
        return (
          <div key={key} {...cellProps} className={cx(styles.cell, styles.typeCell)}>
            <span>-</span>
          </div>
        );
      }

      return (
        <div key={key} {...cellProps} className={cx(styles.cell, styles.typeCell)}>
          <Tooltip content={formatDate(deletedDate, { dateStyle: 'full', timeStyle: 'medium' })}>
            <span>{formatDate(deletedDate, { dateStyle: 'medium', timeStyle: 'short' })}</span>
          </Tooltip>
        </div>
      );
    },
  };
}

function makeTypeColumn(
  response: QueryResponse,
  kindField: Field<string>,
  typeField: Field<string>,
  width: number,
  styles: Record<string, string>,
  panelPluginMetas: PanelPluginMetas
): TableColumn {
  return {
    id: `column-type`,
    field: kindField ?? typeField,
    Header: t('search.results-table.type-header', 'Type'),
    Cell: (p) => {
      const i = p.row.index;
      const kind = kindField?.values[i] ?? 'dashboard';
      let icon: IconName = 'apps';
      let txt = 'Dashboard';
      if (kind) {
        txt = kind;
        switch (txt) {
          case 'dashboard':
            txt = t('search.results-table.type-dashboard', 'Dashboard');
            break;

          case 'folder':
            icon = 'folder';
            txt = t('search.results-table.type-folder', 'Folder');
            break;

          case 'panel':
            icon = `${PluginIconName.panel}`;
            const type = typeField.values[i];
            if (type) {
              txt = type;
              const info = panelPluginMetas[txt];
              if (info?.name) {
                txt = info.name;
              } else {
                switch (type) {
                  case 'row':
                    txt = 'Row';
                    icon = `bars`;
                    break;
                  case 'singlestat': // auto-migration
                    txt = 'Singlestat';
                    break;
                  default:
                    icon = `question-circle`; // plugin not found
                }
              }
            }
            break;
        }
      }
      const { key, ...cellProps } = p.cellProps;
      return (
        <div key={key} {...cellProps} className={cx(styles.cell, styles.typeCell)}>
          {!response.isItemLoaded(p.row.index) ? (
            <Skeleton width={100} />
          ) : (
            <>
              <Icon name={icon} size="sm" title={txt} className={styles.typeIcon} />
              {txt}
            </>
          )}
        </div>
      );
    },
    width,
  };
}

function makeTagsColumn(
  response: QueryResponse,
  field: Field<string[]>,
  width: number,
  styles: Record<string, string>,
  onTagSelected: (tag: string) => void
): TableColumn {
  return {
    Cell: (p) => {
      const tags = field.values[p.row.index];
      const { key, ...cellProps } = p.cellProps;
      return (
        <div key={key} {...cellProps} className={styles.cell}>
          {!response.isItemLoaded(p.row.index) ? (
            <TagList.Skeleton />
          ) : (
            <>{tags ? <TagList className={styles.tagList} tags={tags} onClick={onTagSelected} /> : null}</>
          )}
        </div>
      );
    },
    id: `column-tags`,
    field: field,
    Header: t('search.results-table.tags-header', 'Tags'),
    width,
  };
}

function getDisplayValue({
  kind,
  sortField,
  index,
  getDisplay,
}: {
  kind: Field;
  sortField: Field;
  index: number;
  getDisplay: DisplayProcessor;
}) {
  const value = sortField.values[index];
  if (value == null || (['folder', 'panel'].includes(kind.values[index]) && value === 0)) {
    return '-';
  }
  return formattedValueToString(getDisplay(value));
}
